mapper.select:
SELECT id, user_id, real_name, age, height_cm, weight_kg, phone, practitioner_id FROM t_patient_profile  AND id = #{id}
 AND user_id = #{userId}
 AND real_name LIKE CONCAT('%', #{realName}, '%')
 AND age = #{age}
 AND height_cm = #{heightCm}
 AND weight_kg = #{weightKg}
 AND phone LIKE CONCAT('%', #{phone}, '%')
 AND practitioner_id = #{practitionerId} ORDER BY id DESC
